window.docContents[179].resolve({"/releases/v4.16.0/#Lean-__________________--Release-Notes--Lean-4___16___0-_LPAR_2025-02-03_RPAR_--Highlights":{"contents":"\n\n\n\n\n\n\n\n\n\n","context":"Lean 中文参考手册\u0009Release Notes\u0009Lean 4.16.0 (2025-02-03)","header":"Highlights","id":"/releases/v4.16.0/#Lean-__________________--Release-Notes--Lean-4___16___0-_LPAR_2025-02-03_RPAR_--Highlights"},"/releases/v4.31.0/#Lean-__________________--Release-Notes--Lean-4___31___0-_LPAR_2026-06-13_RPAR_--Highlights":{"contents":"Lean 4.31.0 is a consolidation-heavy release: alongside a handful of new user-facing features — do blocks elaboration, Lake built-in linting, and richer editor hovers — it lands a large, coordinated effort to make definitional-equality checking properly respect transparency levels, a faster and reimplemented mvcgen', significant development in libraries including HTTP, and broad performance work including an LLVM 22 upgrade.\n\nThis highlights section was contributed by Juanjo Madrigal.\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Lean 中文参考手册\u0009Release Notes\u0009Lean 4.31.0 (2026-06-13)","header":"Highlights","id":"/releases/v4.31.0/#Lean-__________________--Release-Notes--Lean-4___31___0-_LPAR_2026-06-13_RPAR_--Highlights"}});